    {"id": 9, "name": "Soul Protect", "category": "Magic", "users": ["Medusa Gorgon", "Arachne Gorgon", "Eruka Frog", "Kim Diehl", "Mizune Family"], "description": "A spell that conceals a witch's soul wavelength and allows them to avoid detection by people using Soul Perception.", "continuity": "Manga and Anime"},
    {"id": 10, "name": "Soul Possession", "category": "Soul Ability", "users": ["Masamune Nakatsukasa"], "description": "The ability to invade and control another person's body by attaching the user's soul to the victim's soul.", "continuity": "Manga and Anime"},
    {"id": 11, "name": "Soul Meditation", "category": "Soul Ability", "users": ["Black Star"], "description": "A meditative practice used to enter the internal world of the soul, confront personal weaknesses and strengthen spiritual control.", "continuity": "Manga"},
