    {"id": 13, "name": "Soul Threads: Diffuse Sutures", "category": "Soul Ability", "users": ["Franken Stein"], "description": "An expanded Soul Thread technique that spreads numerous wavelength threads throughout an area to restrain or manipulate several targets.", "continuity": "Manga"},
    {"id": 14, "name": "Witch Hunter", "category": "Soul Resonance", "users": ["Maka Albarn", "Soul Eater Evans", "Franken Stein", "Spirit Albarn"], "description": "A scythe-based Soul Resonance technique that enlarges and reshapes the blade to increase its cutting power, particularly against witches.", "continuity": "Manga and Anime"},
    {"id": 15, "name": "Genie Hunter", "category": "Soul Resonance", "users": ["Maka Albarn", "Soul Eater Evans"], "description": "An advanced form of Witch Hunter strengthened by Maka's Anti-Demon Wavelength, producing a larger and more powerful scythe blade.", "continuity": "Anime"},
    {"id": 16, "name": "Demon Hunt", "category": "Soul Resonance", "users": ["Maka Albarn", "Soul Eater Evans"], "description": "An advanced scythe resonance attack developed beyond Witch Hunter and used against powerful supernatural enemies.", "continuity": "Manga"},
    {"id": 17, "name": "Kishin Hunt", "category": "Soul Resonance", "users": ["Maka Albarn", "Soul Eater Evans"], "description": "A finishing attack performed while Maka and Soul control the Black Blood Armor, allowing them to strike Asura from within and cause severe damage.", "continuity": "Manga"},
