    {"id": 19, "name": "Partial-Weapon Transformation", "category": "Weapon Ability", "users": ["Soul Eater Evans", "Spirit Albarn", "Justin Law", "Giriko"], "description": "The ability of a demon weapon to transform only part of their body into a blade, barrel, chain or another weapon component.", "continuity": "Manga and Anime"},
    {"id": 20, "name": "Multi-Form Transformation", "category": "Weapon Ability", "users": ["Tsubaki Nakatsukasa"], "description": "Tsubaki's inherited ability to transform into several different ninja weapons, including a chain scythe, smoke bomb, shuriken and ninja sword.", "continuity": "Manga and Anime"},
