    {"id": 22, "name": "Shadow Star Form", "category": "Soul Resonance", "users": ["Black Star", "Tsubaki Nakatsukasa"], "description": "A Soul Resonance technique that allows Tsubaki to manipulate Black Star's shadow as a solid weapon for attacking, cutting and restraining enemies.", "continuity": "Manga and Anime"},
