    {"id": 24, "name": "Shadow Star First Form: Chain of Blackness", "category": "Soul Resonance", "users": ["Black Star", "Tsubaki Nakatsukasa"], "description": "A Shadow Star technique that converts Black Star's shadow into a chain-like weapon used to bind or strike an opponent.", "continuity": "Manga"},
    {"id": 25, "name": "Shadow Star Second Form: Leaf of the Moonlit Night", "category": "Soul Resonance", "users": ["Black Star", "Tsubaki Nakatsukasa"], "description": "A Shadow Star weapon form designed for swift close-range combat and precise sword attacks.", "continuity": "Manga"},
    {"id": 26, "name": "Shadow Star Third Form: Severed Shadow", "category": "Soul Resonance", "users": ["Black Star", "Tsubaki Nakatsukasa"], "description": "A high-speed Shadow Star technique that leaves behind substantial afterimages capable of misleading and interfering with an opponent.", "continuity": "Manga"},
    {"id": 27, "name": "Shadow Star Fourth Form: Branched Darkness", "category": "Soul Resonance", "users": ["Black Star", "Tsubaki Nakatsukasa"], "description": "A Shadow Star technique that divides and extends Black Star's shadow into several branches for attacking multiple points at once.", "continuity": "Manga"},
    {"id": 28, "name": "Shadow Star: Pull and Slash", "category": "Soul Resonance", "users": ["Black Star", "Tsubaki Nakatsukasa"], "description": "A technique that uses a shadow to pull an opponent into range before Black Star follows with a sword strike.", "continuity": "Manga"},
    {"id": 29, "name": "Speed Star", "category": "Soul Resonance", "users": ["Black Star", "Tsubaki Nakatsukasa"], "description": "A Soul Resonance technique focused on increasing Black Star's speed and enabling rapid movement during combat.", "continuity": "Manga"},
    {"id": 30, "name": "Shield Star", "category": "Soul Resonance", "users": ["Black Star", "Tsubaki Nakatsukasa"], "description": "A defensive Soul Resonance technique in which Tsubaki and Black Star form a barrier capable of blocking incoming attacks.", "continuity": "Manga"},
